UPDATE ticket_products
SET status = #{status}
WHERE ticket_product_id = #{ticketProductId}

mapper.select:
SELECT 
FROM ticket_product_options o
WHERE o.ticket_product_option_id = #{optionId}

INSERT INTO ticket_product_options (
    ticket_product_id, name, description, unit_price,
    max_quantity_per_user, sort_order, is_active
) VALUES (
    #{ticketProductId}, #{request.name}, #{request.description}, #{request.unitPrice},
    #{request.maxQuantityPerUser}, #{request.sortOrder}, #{request.isActive}
)
RETURNING ticket_product_option_id

SELECT EXISTS (
    SELECT 1 FROM ticket_product_options
    WHERE ticket_product_id = #{ticketProductId}
      AND (name = #{name} OR sort_order = #{sortOrder})

        AND ticket_product_option_id <> #{optionId}

)

INSERT INTO ticket_time_slots (
    ticket_product_option_id, usage_date, start_time, end_time, status
) VALUES (
    #{optionId}, #{usageDate}, #{startTime}, #{endTime}, 'OPEN'
)
RETURNING ticket_time_slot_id

SELECT EXISTS (
    SELECT 1 FROM ticket_time_slots
    WHERE ticket_product_option_id = #{optionId}
      AND usage_date = #{usageDate}
      AND start_time IS NOT DISTINCT FROM #{startTime}
)

